Q: Creating a python script that calculates large permutations A: <p>Adapt <a href="https://stackoverflow.com/a/353248/125562%5D">C++ solution for Knuth's algorithm</a></p>
<pre><code>; Source - https://stackoverflow.com/a/353248   
; Posted by ShreevatsaR, modified by community. See post 'Timeline' for change history   
; Retrieved 2026-03-07, License - CC BY-SA 3.0   

template \&lt;class BidirectionalIterator\&gt;  
bool next_permutation(BidirectionalIterator first,  
                      BidirectionalIterator last) {  
    if (first == last) return false;  
    BidirectionalIterator i = first;  
    ++i;  
    if (i == last) return false;  
    i = last;  
    --i;  
    for(;;) {  
        BidirectionalIterator ii = i--;  
        if (\*i \&lt;\*ii) {  
            BidirectionalIterator j = last;  
            while (!(\*i \&lt;\*--j));  
            iter_swap(i, j);  
            reverse(ii, last);  
            return true;  
        }  
        if (i == first) {  
            reverse(first, last);  
            return false;  
        }  
    }  
}  
</code></pre>

